import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"泽风大过","description":"周易折中 - 泽风大过","frontmatter":{"title":"泽风大过","description":"周易折中 - 泽风大过"},"headers":[],"relativePath":"zh/classics/zhezhong/034.md","filePath":"zh/classics/zhezhong/034.md"}'),h={name:"zh/classics/zhezhong/034.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="泽风大过" tabindex="-1">泽风大过 <a class="header-anchor" href="#泽风大过" aria-label="Permalink to “泽风大过”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>大过序卦：“颐者，养也。不养则不可动，故受之以大过。凡物养而后能成，成则能动，动则有过。大过所以次颐也。为卦上兑下巽，泽在木上，灭木也。泽者，润养于木，乃至灭没于木，为大过之义。大过者，阳过也，故为大者过，过之大与大事过也。圣贤道德功业大过于人，凡事之大过于常者皆是也。夫圣人尽人道，非过于理也。其制事以天下之正理，矫时之用小过于中者，则有之，如行过乎恭，丧过乎哀，用过乎俭是也。盖矫之小过，而后能及于中，乃求中之用也。所谓大过者，常事之大者耳，非有过于理也。惟其大，故不常见，以其比常所见者大，故谓之大过。如尧舜之禅让，汤武之放伐，皆由道也，道无不中，无不常，以世人所不常见，故谓之大过于常也。”</p><p>大过：栋桡，利有攸往，亨</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>大阳也，四阳居中过盛，故为大过。上下二阴不胜其重，故有栋桡之象。又以四阳虽过，而二五得中，内巽外说，有可行之道，故利有所往而得亨也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>小过阴过于上下，大过阳过于中。阳过于中而上下弱矣，故为栋桡之象。栋取其胜重，四阳聚于中可谓重矣。九三、九四皆取栋象，谓任重也。桡取其本末弱，中强而本末弱，是以桡也。阴弱而阳强，君子盛而小人衰，故利有攸往而亨也。栋，今人谓之檩。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰 ：天下之事固有正理，岂可过耶？然古今固有所谓非常之事者，以理而论，亦无非君子之时中。特其事大𫝑重，不常见尔。</p></li><li><p>朱子语类 ：问大过、小过，先生与伊川之说不同。曰然，伊川此论正如以反经合道为非相似。殊不知大过自有大过时节，小过自有小过时节。处大过之时，则当为大过之事；处小过之时，则当为小过之事。在事虽是过，然适当其时，合当如此作，便是合义。</p></li><li><p>胡氏一桂曰 ：或疑颐与大过对者也，何不名为小过？中孚与小过对者也，何不名为大过？盖大过以四阳在中言，小过以四阴在外言。此是圣人内阳外阴之意。</p></li><li><p>胡氏炳文曰 ：既曰栋桡，又曰利有攸往亨，何也？曰：栋桡以卦象言也，利往而后亨，是不可无大有为之才。而天下亦无不可为之事，以占言也。</p></li><li><p>何氏楷曰 ：栋，《说文》谓之极，《尔雅》谓之桴，其义皆训中也。即屋之脊檩。惟大过是以栋桡，是以利有攸往，惟有攸往，是以亨。翼传乃字当玩。卦辞言栋，概指二三四五言也；爻辞专及三四者，举中枢也。</p></li></ul><p>象曰：泽灭木，大过；君子以独立不惧，遁世无闷</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>泽灭于木，大过之象也。不惧无闷，大过之行也。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>泽润养于木者也，乃至灭没于木，则过甚矣，故为大过。君子观大过之象，以立其大过人之行。君子所以大过人者，以其能独立不惧，遁世无闷也。天下非之而不顾，独立不惧也；举世不见知而不悔，遁世无闷也。如此然后能自守，所以为大过人也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏牧曰 ：用之则独立不惧，舍之则遁世无闷。</p></li><li><p>赵氏汝梅曰 ：独立如巽木，无闷如兑说。</p></li><li><p>李氏简曰 ：君子进则大有为，独立不惧可也；或退而穷居，则坚贞不移，遁世无闷可也。皆大过之事。</p></li></ul><p>彖曰：大过，大者过也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>大者过，谓阳过也。在事为事之大者过，与其过之大。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰：大过谓阳之过也。在人事，则泛言万事大者之过，凡大者皆是非一端也。</li></ul><p>栋桡，本末弱也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>复以卦体释卦辞。本谓初，末谓上，弱谓阴柔。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>谓上下二阴衰弱，阳盛则阴衰，故为大者过。在小过则曰小者过，阴过也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰：刚过始致本末之弱。本末既弱，刚亦不能独支。本末弱即大过之象，乃栋所由桡也。</li></ul><p>刚过而中巽而说，行利有攸往，乃亨</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>又以卦体、卦德释卦辞。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>言卦才之善也。刚虽过而二五皆得中，是处不失中道也。下巽上兑，是以巽顺和说之道而行也。在大过之时，以中道巽说而行，故利有攸往，乃所以能亨也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱氏震曰：刚过而中，所谓时中也。过非过于理也，以过为中也。犹之治疾，疾势沈痼，必攻之以瞑眩之药。自其治微疾之道视之，则谓之过；自药病相对言之，则谓之中。大过之时，君子过越常分以济弱，能达乎时中矣。</p></li><li><p>项氏安世曰：“栋桡”二字以六爻之象言之，中四爻强，初上二爻弱，有栋桡之象，此祸变之大者也。“利有攸往亨”以六爻之才言之，中四爻刚虽大过，而得时措之中，初上二爻又能巽而说，不失人心，故利于有行，虽遇大变而可以亨。此才略之大者也。“巽而说”之下加“行”字者，能以巽说而行，是以利有攸往也。又曰：先言亨后言利有攸往者，亨自亨利，自利也。今先言利有攸往后言亨者，明亨因于往也。故彖曰“利有攸往乃亨”，言往乃亨，不往则不亨也。</p></li></ul><p>大过之时大矣哉</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>大过之时，非有大过人之材不能济也，故叹其大。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>大过之时，其事甚大，故赞之曰大矣哉。如立非常之大事，兴不世之大功，成绝俗之大德，皆大过之事也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰：大过之事甚大，无其时不可过，有其时无其才愈不可过。</p></li><li><p>蔡氏清曰：大过之时，非时大过也，人当大过之时也。以其时事宜于大过也，其理正小过所谓过以利贞与时行者也。大过二字属人。</p></li></ul><p>初六：藉用白茅，无咎</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>当大过之时，以阴柔居巽下，过于畏慎而无咎者也。故其象占如此。白茅，物之洁者。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>初以阴柔巽体而处下，过于畏慎者也。以柔在下，用茅藉物之象，不错诸地而藉以茅，过于慎也，是以无咎。茅之为物，虽薄而用可重，以用之能成敬慎之道也。慎守斯术而行，岂冇失乎大过之用也？系辞云：“苟错诸地而可矣，藉之用茅，何咎之有？”慎之至也。夫茅之为物，薄而用可重也。慎斯术也以往，其无所失矣。言敬慎之至也。茅虽至薄之物，然用之可甚重，以之藉荐则为重慎之道，是用之重也。人之过于敬慎，为之非难，而可以保其安而无过。苟能慎斯道，推而行之于事，其无所失矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰 ：为事之始，不可轻易，必须恭慎，然后可以免咎。况居大过之时，是其事至重，功业至大，尤不易于有为，必当过分而慎重，然后可也。苟于事始慎之如此，则可以立天下之大功，兴天下之大利，又何咎之有哉？</p></li><li><p>朱氏震曰 ：茅之为物，薄而用重，过慎也。过慎者，慎之至也。大过君子将有事焉，以任至大之事，过而无咎者，其惟过于慎乎？过非正也，初六执柔处下，不犯乎刚，于此而过，其谁咎之？</p></li><li><p>赵氏玉泉曰 ：当过时而阴居巽下，是以过慎之心任事，谨始虑终，无所不至。如物措诸地，又藉之以白茅焉。如是，则视天下无可忽之事者，举天下无不可为之事，身无过动，行无败谋，何咎之有？</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>胡氏、朱氏、赵氏说极于卦义相关。盖大过者，大事之卦也。自古任大事者，必以小心为基。故圣人于初爻发义，任重大者栋也，基细微者茅也。栋支于上，茅藉于下，故系传云：“茅之为物，薄而用可重也。”正对栋为重物、重任而言。</p><p>象曰：藉用白茅，柔在下也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>以阴柔处卑下之道，唯当过于敬慎而已。以柔在下为以茅藉物之象，敬慎之道也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>钱氏志立曰 ：以卦象论之，初与四应而在下，初者四之本也。本弱而藉茅，则敬慎之至，以善处者，故四之栋不至于倾也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>高以下为基，刚以柔为本，柔在下对刚在上。</p><p>九二：枯杨生稊，老夫得其女妻，无不利</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>阳过之始而比初阴，故其象占如此。稊，根也，荣于下者也。荣于下则生于上矣。夫虽老而得女妻，犹能成生育之功也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>阳之大过比阴，则合，故二与五皆有生象。九二当大过之初，得中而居柔，与初密比而相与。初既切比于二，二复无应于上，其相与可知。是刚过之人而能以中自处，用柔相济者也。过刚则不能有所为，九三是也；得中用柔，则能成大过之功，九二是也。杨者，阳气易感之物，阳过则枯矣。杨枯槁而复生稊，阳过而未至于极也。九二阳过而与初，老夫得女妻之象。老夫而得女妻，则能成生育之功。二得中居柔而与初，故能复生稊而无过极之失，无所不利也。在大过，阳爻居阴则善，二与四是也。二不言吉，方言无所不利，未遽至吉也。稊，根也。刘琨《劝进表》云：“生繁华于枯荑。”谓枯根也。郑康成《易》亦作“荑”字，与稊同。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>司马氏光曰 ：大过，刚已过矣，止可济之以柔，不可济之以刚也。故大过之时，皆以居阴为吉，不以得位为美。</p></li><li><p>杨氏时曰 ：闻之蜀僧云，四爻之刚虽同为木，然或为杨，或为栋。栋负众榱，则木之强者也；杨为早凋，则木之弱者也。此卦本末皆弱，二近于本，五近于末，故均为木之弱也。</p></li><li><p>项氏安世曰 ：二五皆滨于泽，杨，泽木也。当大过之时，故称枯焉。过则木枯也。</p></li><li><p>王氏申子曰 ：大过诸爻，以刚柔适中者为善。初以柔居刚，二以刚居柔而比之，是刚柔适中，相济而有功者也。其阳过也，如杨之枯，如夫之老；其相济而有功也，如枯杨而生稊，如老夫得女妻。言阳虽过矣，九二处之得中，故无不利。</p></li><li><p>胡氏炳文曰 ：巽为木，兑为泽，杨近泽之木，故以取象。枯杨，大过象；稊，初在下象；老夫，九象；女妻，初柔在下象。九二阳虽过，而下比于阴，如枯杨虽过于老，稊荣于下则复生于上矣。老夫而得女妻，虽过以相与，终能成生育之功。无他，以阳从阴，过而不过生道也。</p></li></ul><p>象曰：老夫女妻，过以相与也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>老夫之说少女，少女之顺老夫，其相与过于常分，谓九二初六阴阳相与之和过于常也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏申子曰 ：老夫而女妻，虽过乎常，然阴阳相与以成生育之功，则无不利也。</li></ul><p>九三：栋桡，凶</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>三四二爻居卦之中，栋之象也。九三以刚居刚，不胜其重，故象桡而占凶。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>夫居大过之时，兴大过之功，立大过之事，非刚柔得中，取于人以自辅，则不能也。既过于刚强，则不能与人同常，常之功尚不能独立，况大过之事乎？以圣人之才，虽小事必取于人，当天下之大任，则可知矣。九三以大过之阳，复以刚自居而不得中，刚过之甚者也。以过甚之刚动，则违于中和而拂于众心，安能当大过之任乎？故不胜其任，如栋之桡，倾败其室，是以凶也。取栋为象者，以其无辅而不能胜重任也。或曰：“三巽体而应于上，岂无用柔之象乎？”曰：“言易者贵乎识𫝑之重轻，时之变易。三居过而用刚，巽既终而且变，岂复有用柔之义？应者，谓志相从也。三方过刚，上能系其志乎？”</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>俞氏琰曰 ：卦有四刚爻，而九三过刚特甚，故以卦之栋桡属之。</p></li><li><p>呉氏曰 ：九三栋桡，自桡也。所谓“太刚则折”，故彖有取于“刚过而中，巽而说行”也。</p></li></ul><p>象曰：栋桡之凶，不可以有辅也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>刚强之过则不能取于人，人亦不能亲辅之，如栋桡折不可支辅也。栋当室之中，不可加助，是不可以有辅也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏时曰 ：栋居中而众材辅之者也。九三以刚居刚，过而不中，刚过而不中则不可以有辅，此栋之所以桡也。</p></li><li><p>项氏安世曰 ：全卦有栋桡之象，而九三乃独有之；全卦有利往之象，而九二乃独有之。盖九二当刚过之时，独能居柔而用中，在六爻之中独此一爻不过，故无不利也。卦体本以中太强而本末弱，是以为桡。九三以刚居刚，在六爻之中独此一爻为过，故栋愈桡而不可辅也。</p></li></ul><p>九四：栋隆，吉；有它吝</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以阳居阴，过而不过，故其象隆而占吉。然下应初六，以柔济之，则过于柔矣，故又戒以有它则吝也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>四居近君之位，当大过之任者也。居柔为能用柔相济，既不过刚，则能胜其任，如栋之隆起，是以吉也。隆起取不下桡之义。大过之时，非阳刚不能济，以刚处柔为得宜矣。若又与初六之阴相应，则过也。既刚柔得宜而志复应阴，是有它也，有它则有累于刚，虽未至于大害，亦可吝也。盖大过之时，动则过也。有它，谓更有他志。吝，为不足之义，谓可少也。或曰：“二比初则无不利，四若应初则为吝，何也？”曰：“二得中而比于初，为以柔相济之义；四与初为正应，志相系者也。九既居四，刚柔得宜矣，复牵系于阴以害其刚，则可吝也。”</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏牧曰 ：大过之时，阳爻皆以居阴为美。有应，则有它吝。</p></li><li><p>李氏过曰 ：下卦上实而下弱，下弱则上倾。故三居下卦之上而曰栋桡凶，言下弱而无助也。上卦上弱而下实，下实则可载。故四居上卦之下而曰栋隆吉，言下实而不桡也。此二爻当分上下体㸔。</p></li><li><p>胡氏炳文曰 ：屋以栋为中，三视四则在下，栋桡于下之象；四在上，栋隆于上之象。</p></li><li><p>呉氏曰 ：三四居卦之中，皆有栋象。三桡而四隆者，三以刚居刚，四以刚居柔也；三在下，四在上也；三于下卦为上实下虚，四于上卦为下实上虚也。</p></li></ul><p>象曰：栋隆之吉，不桡乎下也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>栋隆起则吉，不桡曲以就下也，谓不下系于初也。</p><p>九五：枯杨生华，老妇得其士夫，无咎无誉</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>九五阳过之极，又比过极之阴，故其象占皆与二反。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>九五当大过之时，本以中正居尊位，然下尢应助，固不能成大过之功；而上比过极之阴，其所相济者如枯杨之生华。枯杨下生根稊，则能复生，如大过之阳兴成事功也；上生华秀，虽冇所发，无益于枯也。上六过极之阴，老妇也；五虽非少，比老妇则为壮矣，于五无所赖也。故反称妇，得过极之阴得阳之相济，不为无益也。以士夫而得老妇，虽无罪咎，殊非美也，故云“无咎无誉”。象复言其可丑也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>沈氏该曰 ：九二比于初，近本也，生稊之象也；九五承于上，近未也，生华之象也。</p></li><li><p>何氏楷曰 ：生稊则生机方长，生华则泄且竭矣。二所与者初，初本也，又巽之主爻，为木、为长、为髙木。已过而复芽，又长且高，故有往亨之理。五所与者上，上末也，又兑之主爻，为毁折、为附决，皆非木之所宜。木已过而生华，又毁且折，理无久生已。</p></li></ul><p>象曰：枯杨生华，何可久也；老妇士夫，亦可丑也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>枯杨不生根而生华，旋复枯矣，安能久乎？老妇而得士夫，岂能成生育之功，亦为可丑也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰 ：稊者顚而复蘖，反其始也；华者盈而毕发，速其终也。</p></li><li><p>项氏安世曰 ：二五皆无正应而过以与阴者也。二所与者初，初本也，故为稊。稊者，木根新生之芽也，过而复芽，故有往亨之理。五所与者上，上末也，故为华。木已过而生华，故无久生之理也。</p></li><li><p>王氏申子曰 ：木枯而华，是速其枯；老妇士夫，是过乎常而为柔邪所惑。</p></li><li><p>何氏楷曰 ：盛极将枯而又生华，以自秏竭，不能久矣。二以刚居柔，初以柔居刚，此未甚过者也，又在卦初，故过以相与可成生育之功。五以刚居刚，上以柔居柔，皆过者也，又在卦终，故阴阳相比祇以为丑。其相反如此。</p></li></ul><p>上六：过涉灭顶，凶；无咎</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>处过极之地，才弱不足以济，然于义为无咎矣。盖段身成仁之事故，其象占如此。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>上六以阴柔处过极，是小人过常之极者也。小人之所谓大过，非能为大过人之事也，直过常越理，不恤危亡，履险蹈祸而已。如过涉于水，至灭没其顶，其凶可知。小人狂躁以自祸，盖其宜也，复将何尤？故曰无咎，言自为之无所怨咎也。因泽之象而取涉义。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>钱氏志立曰 ：泽之灭木，上之所以㓕顶也。虽至㓕顶，然有不容不涉，即不得不过者。孔子所以观卦象而有独立不惧之思也。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>此爻程传以为履险蹈祸之小人，本义以为杀身成仁之君子。本义之说固比程传为长，然又有一说以为大过之极，事无可为者。上六柔为说主，则是能从容随顺而不为刚激，以益重其𫝑，故虽处过涉灭顶之凶而无咎也。如东京之季，范李之徒，适足以推波助澜，非救时之道。况上六居无位之地，委蛇和顺，如申屠蟠、郭泰者，君子弗非也。此说亦可并存。</p><p>象曰：过涉之凶，不可咎也</p><h3 id="程传-18" tabindex="-1">程传 <a class="header-anchor" href="#程传-18" aria-label="Permalink to “程传”">​</a></h3><p>过涉至溺乃自为之，不可以有咎也，言无所怨咎。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li>苏氏轼曰 ：过涉至于灭顶，将有所救也，势不可救而徒犯其害，故凶。然其义则不可咎也。</li></ul><p>总论</p><ul><li><p>冯氏椅曰 ：易大抵上下画停者，从中分反对为象，非他卦相应之例也。颐、中孚、小过皆然，而此卦尤明。三与四对，皆为栋象，上隆下桡也；二与五对，皆为枮杨之象，上革下稊也；初与上对，初为藉用白茅之慎，上为过涉灭顶之凶也。</p></li><li><p>龚氏焕曰 ：大过本为阳过，若复以阳居阳，则愈过矣。故诸爻以阳居阴者皆吉，以阳居阳者皆凶，与大壮诸爻取义略同。</p></li></ul>',123)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
